export const INITIAL_REAL_JOBS: Job[] = records.map(job => ({
  ...common,
  ...job,
  applicationChannel: (job.applicationChannel as ApplicationChannel) || common.applicationChannel,
  applicationTarget: job.applicationTarget || job.sourceUrl || '',
  hideSalary: job.hideSalary ?? (!job.salaryMin),
  salaryCurrency: job.salaryCurrency || common.salaryCurrency,
  state: job.state || common.state,
  status: (job.status as JobStatus) || common.status,
  isFeatured: job.isFeatured ?? common.isFeatured,
  viewsCount: job.viewsCount ?? common.viewsCount,
  createdAt: job.createdAt || common.createdAt,
  verifiedAt: job.verifiedAt || common.verifiedAt,
}));
